<span class="line"><span style="color:#ABB2BF;">    original_query: </span><span style="color:#56B6C2;">str</span><span style="color:#56B6C2;"> =</span><span style="color:#61AFEF;"> Field</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">description</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;原始查询&quot;</span><span style="color:#ABB2BF;">)</span></span>
